#include <stdint.h>

typedef float float32_t;

void vectorized_s258(int iterations, float* a, float* b, float* c, float* d, float* e, float aa[256][256])
{
    if (iterations <= 0) return;

    for (int nl = 0; nl < iterations; nl++) {
        float s = 0.0f;
        for (int i = 0; i < 256; i += 4) {
            float32_t a_vec[4] = {a[i], a[i+1], a[i+2], a[i+3]};
            float32_t d_vec[4] = {d[i], d[i+1], d[i+2], d[i+3]};
            float32_t c_vec[4] = {c[i], c[i+1], c[i+2], c[i+3]};
            float32_t aa0_vec[4] = {aa[0][i], aa[0][i+1], aa[0][i+2], aa[0][i+3]};

            float32_t s_vec[4];
            float cur_s = s;
            for (int j = 0; j < 4; j++) {
                if (a_vec[j] > 0.0f) {
                    cur_s = d_vec[j] * d_vec[j];
                }
                s_vec[j] = cur_s;
            }

            for (int j = 0; j < 4; j++) {
                b[i + j] = s_vec[j] * c_vec[j] + d_vec[j];
                e[i + j] = (s_vec[j] + 1.0f) * aa0_vec[j];
            }

            // Update s for next chunk: find last positive a in this chunk
            int found = 0;
            for (int j = 3; j >= 0; j--) {
                if (a_vec[j] > 0.0f) {
                    s = d_vec[j] * d_vec[j];
                    found = 1;
                    break;
                }
            }
            if (!found) {
                s = cur_s;
            }
        }
    }
}

void s258_opt(int iterations, float* a, float* b, float* c, float* d, float* e, float aa[256][256])
{
    for (int nl = 0; nl < iterations; nl++) {
        float s = 0.0f;
        float s_values[256];

        // First loop: compute s for each iteration (reduction pattern)
        for (int i = 0; i < 256; ++i) {
            if (a[i] > 0.0f) {
                s = d[i] * d[i];
            }
            s_values[i] = s;
        }

        // Second loop: use computed s values (vectorizable)
        for (int i = 0; i < 256; ++i) {
            b[i] = s_values[i] * c[i] + d[i];
            e[i] = (s_values[i] + 1.0f) * aa[0][i];
        }
    }
}
